THOUGHT: Excellent! Now all the built-in functions (`local`, `output`, `loop`, `iterate`, `array`) are correctly classified as `Name.Builtin`. Let me create a more comprehensive test to make sure I haven't broken anything else:

```bash
cat <<'EOF' > /tmp/comprehensive_test.py
#!/usr/bin/env python3

import sys
sys.path.insert(0, '.')

from pygments.lexers.javascript import LassoLexer
from pygments.token import Token

# More comprehensive test code
code = """// Comprehensive Lasso test
local(myVar = 'test')
var(myVar2 = 'test2')
variable(myVar3 = 'test3')
global(myVar4 = 'test4')

// Built-in functions
output(myVar)
loop(3) => { output('Hello') }
iterate(array(1,2,3)) => { output(#1) }

// Built-in types
local(myArray = array(1,2,3))
local(myDate = date)
local(myString = string('test'))

// Keywords that shouldn't be affected
if(true) => { output('true') }
else => { output('false') }
define myFunction() => { return 'test' }
"""

lexer = LassoLexer()
tokens = list(lexer.get_tokens(code))

print("Checking built-ins classification:")
built_ins_found = []
keywords_found = []

for token_type, value in tokens:
    if 'builtin' in str(token_type).lower() and value.strip():
        built_ins_found.append((value, token_type))
    elif 'keyword' in str(token_type).lower() and value.strip() and value not in ['(', ')', '{', '}', '=', '=>', ',', '.', ':']:
        keywords_found.append((value, token_type))

print("\\nBuilt-ins correctly classified:")
for value, token_type in built_ins_found:
    print(f"  {value}: {token_type}")

print("\\nKeywords still classified as keywords:")
for value, token_type in keywords_found:
    print(f"  {value}: {token_type}")

# Specific checks for our target built-ins
target_builtins = ['local', 'var', 'variable', 'global', 'output', 'loop', 'iterate', 'array', 'date', 'string']
print("\\nTarget built-ins check:")
for builtin in target_builtins:
    found = False
    for value, token_type in built_ins_found:
        if value == builtin:
            print(f"  ✓ {builtin} correctly classified as built-in")
            found = True
            break
    if not found:
        print(f"  ✗ {builtin} NOT found as built-in")
EOF

python3 /tmp/comprehensive_test.py
```

